import{c as t,Q as a,j as s,m as o}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Password + email OTP","description":"How the default two-step login flow works.","frontmatter":{"title":"Password + email OTP","description":"How the default two-step login flow works."},"headers":[],"relativePath":"auth/password-otp.md","filePath":"auth/password-otp.md"}'),i={name:"auth/password-otp.md"};function r(n,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<p>The default login flow requires both a correct password and a one-time code sent to the user&#39;s email. This is two-factor authentication (2FA) - even if someone steals a user&#39;s password, they still cannot log in without also having access to that user&#39;s inbox.</p><h2 id="step-1-password" tabindex="-1">Step 1: password <a class="header-anchor" href="#step-1-password" aria-label="Permalink to &quot;Step 1: password&quot;">​</a></h2><p>The user goes to <code>/login</code>, enters their email and password, and clicks <strong>Sign in</strong>.</p><p>GateKeeper looks up the user by email, checks the password using argon2id (a slow, memory-hard hashing algorithm that makes brute-force attacks expensive), and if it matches, moves on to step 2.</p><p>If the password is wrong, the login attempt is rejected and logged in the audit log. The error message deliberately does not distinguish between &quot;email not found&quot; and &quot;wrong password&quot; to avoid confirming whether an account exists.</p><p>If the user has a TOTP authenticator app enrolled, they are sent to the TOTP challenge page instead of email OTP. See <a href="/auth/totp.html">TOTP</a> for details.</p><h2 id="step-2-email-otp" tabindex="-1">Step 2: email OTP <a class="header-anchor" href="#step-2-email-otp" aria-label="Permalink to &quot;Step 2: email OTP&quot;">​</a></h2><p>GateKeeper generates a 6-digit code using a cryptographically secure random number generator, stores it with a 10-minute expiry, and sends it to the user&#39;s email.</p><p>A &quot;one-time password&quot; (OTP) is a code that can only be used once and expires after a short time. It adds a second factor because it requires access to the user&#39;s email, not just their password.</p><p>The user enters the code at <code>/login/otp</code>. If it matches and has not expired, the session is established and the user is redirected to their original destination.</p><h2 id="rate-limiting-and-lockout" tabindex="-1">Rate limiting and lockout <a class="header-anchor" href="#rate-limiting-and-lockout" aria-label="Permalink to &quot;Rate limiting and lockout&quot;">​</a></h2><p>To prevent brute-force attacks against the OTP code:</p><ul><li>After 5 failed OTP attempts within 10 minutes, the account is locked out for 10 minutes.</li><li>The lockout resets automatically after the 10-minute window.</li></ul><h2 id="session-establishment" tabindex="-1">Session establishment <a class="header-anchor" href="#session-establishment" aria-label="Permalink to &quot;Session establishment&quot;">​</a></h2><p>After successful OTP verification, GateKeeper creates a server-side session with a 32-byte random token. The session ID is stored in an <code>HttpOnly</code>, <code>Secure</code>, <code>SameSite=Lax</code> cookie. The actual session data (user ID, timestamps) lives in the database, not in the cookie.</p><p>The session lasts for <code>SESSION_TTL_HOURS</code> hours (default 8) and automatically renews on each request, so active users stay logged in.</p>',16)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
